  function switchTextbookModulePreservingFormat(modCode) {
    if (!modCode || /^(ALL|FOLDERS)$/i.test(String(modCode))) {
      if (state.textbookSubMode === "lecture-slides") {
        state.lsDriveScope = "folders";
      } else {
        state.textbookSubMode = "docs-drive";
        state.tbDriveScope = "folders";
      }
      renderTextbookReader();
      window.dispatchEvent(new CustomEvent("racm:tabchange", { detail: { tabId: state.activeTab, role: ROLE } }));
      window.scrollTo({ top: 0, behavior: "smooth" });
      return;
    }
    const clean = /^(HS[1-6]|ST1)$/i.test(String(modCode || "")) ? String(modCode).toUpperCase() : "HS1";
    state.activeHsModule = clean;
    if (state.textbookSubMode === "doc-reader") {
      state.activeDocId = resolveDocIdForModuleAndFormat(clean, state.preferredHsFormat || "concise");
    } else if (state.textbookSubMode === "lecture-slides") {
      state.lsDriveScope = "module";
    } else {
      state.tbDriveScope = "module";
    }
    renderTextbookReader();
    window.dispatchEvent(new CustomEvent("racm:tabchange", { detail: { tabId: state.activeTab, role: ROLE } }));
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function openTextbookDriveFolder(modCode) {
    state.textbookSubMode = "docs-drive";
    if (!modCode || /^(ALL|FOLDERS)$/i.test(String(modCode))) {
      state.tbDriveScope = "folders";
    } else if (/^(HS[1-6]|ST1)$/i.test(String(modCode))) {
      state.activeHsModule = String(modCode).toUpperCase();
      state.tbDriveScope = "module";
    } else {
      state.tbDriveScope = "folders";
    }
    switchTab("textbooks");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function openHsLectureSlides(modCode) {
    state.textbookSubMode = "lecture-slides";
    if (!modCode || /^(ALL|FOLDERS)$/i.test(String(modCode))) {
      state.lsDriveScope = "folders";
    } else if (/^(HS[1-6]|ST1)$/i.test(String(modCode))) {
      state.activeHsModule = String(modCode).toUpperCase();
      state.lsDriveScope = "module";
    } else {
      state.lsDriveScope = "folders";
    }
    switchTab("textbooks");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function openSelfQuizForModule(modCode, subTab) {
    const clean = /^(HS[1-6]|ST1)$/i.test(String(modCode || "")) ? String(modCode).toUpperCase() : "";
    if (clean) state.activeHsModule = clean;
    const nextSub = subTab || "qa";
    state.practiceSub = nextSub;
    document.querySelectorAll("[data-practice-sub]").forEach((b) =>
      b.setAttribute("aria-pressed", b.dataset.practiceSub === nextSub ? "true" : "false")
    );
    if ($("practiceModuleFilter")) {
      $("practiceModuleFilter").value = clean;
    }
    switchTab("practice");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  function openCaseDiscussionScrollForModule(modCode) {
    const clean = /^HS[1-6]$/i.test(String(modCode || "")) ? String(modCode).toUpperCase() : "ALL";
    state.hsdViewMode = "scroll";
    state.hsdModule = clean;
    if (/^HS[1-6]$/.test(clean)) {
      state.activeHsModule = clean;
      state.hsdSlideDeckMod = clean;
    }
    state.hsdDriveFolderOpen = false;
    try {
      localStorage.setItem("racm303_hsd_vmode", "scroll");
    } catch (_) {}
    if ($("hsdModuleSelect")) $("hsdModuleSelect").value = clean;
    if (typeof syncViewModeButtonsUI === "function") syncViewModeButtonsUI();
    switchTab("hs-discussion");
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

