      `<span>${state.pptPopupConnected ? "กำลัง Share Slide ↗" : "Share Slide"}</span>`;
    shareSlideBtn.addEventListener("click", () => openPptSlideShareWindow());

    const showBarBtn = make("button", null, "ppt-view-ico-btn is-slideshow-btn");
